import cv2 as cv
import base64
import numpy as np
import math
import sys
#входные данные
line1 = "615.0 0.0 320.0 0.0 615.0 240.0 0.0 0.0 1.0" #sys.stdin.readline().strip()
K_values = list(map(float, line1.split()))
print(K_values)
K = np.array(K_values).reshape(3,3)
line2 = 3 #sys.stdin.readline().strip()
M = int(line2)
images_base64 = []
imag1=""
images_base64.append(imag1)
imag2=""
images_base64.append(imag2)
imag3=""
images_base64.append(imag3)

# print (images_base64)
#for _ in range(M):
    #image_string = sys.stdin.readline().strip()
    #images_base64.append(image_string)
#изображения
images = []
for image_b64 in images_base64:
    # buffer = image_b64.encode('utf-8')
    # array = np.frombuffer(buffer, dtype=np.uint8)
    # img = cv.imdecode(array, cv.IMREAD_GRAYSCALE)
    buffer = base64.b64decode(image_b64)
    array = np.frombuffer(buffer, dtype=np.uint8)
    img = cv.imdecode(array, flags=1)

    images.append(img)
# print(images)
#матрицы
t_global = np.zeros((3, 1))
r_global = np.eye(3)
#позиции
positions = [tuple(t_global[:, 0])]
#пары изображений


orb = cv.ORB_create()
bf = cv.BFMatcher(cv.NORM_HAMMING)


for i in range(M-1):
    #ключевые точки
    pic1 = images[i]
    pic1 = cv.cvtColor(pic1, cv.COLOR_BGR2GRAY)
    pic2 = images[i+1]
    pic2 = cv.cvtColor(pic2, cv.COLOR_BGR2GRAY)
    kp1, des1 = orb.detectAndCompute(pic1, None)
    kp2, des2 = orb.detectAndCompute(pic2, None)
    raw_matches = bf.knnMatch(des1, des2, k=2)
    # print(len(raw_matches))
    #пары
    matches = []
    for m, n in raw_matches:
        if m.distance < 0.8 * n.distance:
            matches.append(m)
    #сортировка
    good = sorted(matches, key=lambda x: x.distance)
    matches = good[:50]
    # print(matches)
    points1 = np.float32([kp1[m.queryIdx].pt for m in matches])
    points2 = np.float32([kp2[m.trainIdx].pt for m in matches])
    #эссенциальная матрица
    E, _ = cv.findEssentialMat(points1, points2, K, method=cv.RANSAC)
    print (E)
    # r, t
    _, r, t, _ =cv.recoverPose(E, points1, points2, K)
    print (r)
    print (t)
    #обнова матриц
    t_global = t_global + r_global @ t
    r_global = r @ r_global
    #обнова позиции
    positions.append(tuple(t_global[:, 0]))
print (positions)

